import { createHash } from "node:crypto";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";
import { and, eq, isNull } from "drizzle-orm";
import { audit, emitEvent, notFound, badRequest, type RequestContext } from "@office/core";
import { documents, uuidv7, type Tx } from "@office/db";

/** Where file bytes live. Keys are generated by the platform (`<tenantId>/<documentId>`), never by users. */
export interface BlobStore {
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  delete(key: string): Promise<void>;
}

/** Local directory (dev, tests, single-node self-host). */
export class FsBlobStore implements BlobStore {
  private root: string;
  constructor(dir: string) { this.root = resolve(dir); }
  private path(key: string) {
    const p = resolve(this.root, key);
    if (!p.startsWith(this.root + sep)) throw new Error("invalid storage key");
    return p;
  }
  async put(key: string, bytes: Uint8Array) { const p = this.path(key); await mkdir(dirname(p), { recursive: true }); await writeFile(p, bytes, { mode: 0o600 }); }
  async get(key: string) { return new Uint8Array(await readFile(this.path(key))); }
  async delete(key: string) { await rm(this.path(key), { force: true }); }
}

export interface S3Config { bucket: string; region: string; endpoint?: string | undefined; accessKeyId?: string | undefined; secretAccessKey?: string | undefined; forcePathStyle?: boolean }

/** S3 or any S3-compatible store (MinIO, R2, …). Server-side encryption requested on every put. */
export class S3BlobStore implements BlobStore {
  private client: Promise<import("@aws-sdk/client-s3").S3Client>;
  constructor(private cfg: S3Config) {
    this.client = import("@aws-sdk/client-s3").then(({ S3Client }) => new S3Client({
      region: cfg.region, forcePathStyle: cfg.forcePathStyle ?? !!cfg.endpoint,
      ...(cfg.endpoint ? { endpoint: cfg.endpoint } : {}),
      ...(cfg.accessKeyId && cfg.secretAccessKey ? { credentials: { accessKeyId: cfg.accessKeyId, secretAccessKey: cfg.secretAccessKey } } : {}),
    }));
  }
  async put(key: string, bytes: Uint8Array, contentType: string) {
    const { PutObjectCommand } = await import("@aws-sdk/client-s3");
    await (await this.client).send(new PutObjectCommand({ Bucket: this.cfg.bucket, Key: key, Body: bytes, ContentType: contentType, ServerSideEncryption: "AES256" }));
  }
  async get(key: string) {
    const { GetObjectCommand } = await import("@aws-sdk/client-s3");
    const r = await (await this.client).send(new GetObjectCommand({ Bucket: this.cfg.bucket, Key: key }));
    return r.Body!.transformToByteArray();
  }
  async delete(key: string) {
    const { DeleteObjectCommand } = await import("@aws-sdk/client-s3");
    await (await this.client).send(new DeleteObjectCommand({ Bucket: this.cfg.bucket, Key: key }));
  }
}

// ───────────────────────── type detection ─────────────────────────
/** Allowed upload types. Detected from content (magic bytes), not trusted from the client. No HTML/SVG/scripts. */
export const ALLOWED_TYPES = ["application/pdf", "image/png", "image/jpeg", "image/webp", "image/gif", "text/plain", "text/csv"] as const;
export type AllowedType = (typeof ALLOWED_TYPES)[number];

export function sniffType(b: Uint8Array, declared?: string, filename?: string): AllowedType | null {
  const starts = (...sig: number[]) => sig.every((v, i) => b[i] === v);
  if (starts(0x25, 0x50, 0x44, 0x46, 0x2d)) return "application/pdf";
  if (starts(0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a)) return "image/png";
  if (starts(0xff, 0xd8, 0xff)) return "image/jpeg";
  if (starts(0x47, 0x49, 0x46, 0x38)) return "image/gif";
  if (starts(0x52, 0x49, 0x46, 0x46) && b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50) return "image/webp";
  // Text: valid UTF-8, no NUL, and not markup.
  const head = b.subarray(0, 4096);
  if (head.includes(0)) return null;
  let text: string;
  try { text = new TextDecoder("utf-8", { fatal: true }).decode(head); } catch { return null; }
  if (/^\s*</.test(text)) return null;
  const csv = declared === "text/csv" || /\.csv$/i.test(filename ?? "");
  return csv ? "text/csv" : "text/plain";
}

export const safeFilename = (name: string) =>
  (name.split(/[\\/]/).pop() ?? "file").normalize("NFKC").replace(/[^\w.\- ()]+/g, "_").replace(/^\.+/, "").slice(0, 120) || "file";

/** Inline display is allowed only for types browsers render without running content. */
export const inlineSafe = (mime: string) => mime === "application/pdf" || mime.startsWith("image/");

// ───────────────────────── service ─────────────────────────
export interface FileDeps { blobs: BlobStore; maxBytes: number }
export interface StoredFile { id: string; title: string; filename: string; mime: string; size: number; sha256: string; module: string | null; createdAt: Date }
export interface NewFile { filename: string; bytes: Uint8Array; declaredType?: string | undefined; title?: string | undefined; folder?: string | undefined }

const toStored = (r: typeof documents.$inferSelect): StoredFile => ({
  id: r.id, title: r.title, filename: r.filename ?? r.title, mime: r.mime ?? "application/octet-stream", size: r.size ?? 0,
  sha256: r.sha256 ?? "", module: r.module, createdAt: r.createdAt,
});

/**
 * Validate (size, detected type), write bytes, then insert the document row in the caller's tenant tx.
 * If the tx later rolls back the blob is orphaned (harmless; a sweep can remove keys without rows).
 * `module` set => module-private document.
 */
export async function storeFile(tx: Tx, ctx: RequestContext, d: FileDeps, f: NewFile, module: string | null = null): Promise<StoredFile> {
  if (!f.bytes.length) throw badRequest("File is empty");
  if (f.bytes.length > d.maxBytes) throw badRequest(`File is larger than ${Math.floor(d.maxBytes / 1_048_576)} MB`);
  const filename = safeFilename(f.filename);
  const mime = sniffType(f.bytes, f.declaredType, filename);
  if (!mime) throw badRequest(`Unsupported file type. Allowed: PDF, PNG, JPEG, WebP, GIF, plain text, CSV`);
  const id = uuidv7();
  const key = `${ctx.tenantId}/${id}`;
  const sha256 = createHash("sha256").update(f.bytes).digest("hex");
  await d.blobs.put(key, f.bytes, mime);
  const [row] = await tx.insert(documents).values({
    id, tenantId: ctx.tenantId, title: (f.title?.trim() || filename).slice(0, 300), filename, storageKey: key, mime,
    size: f.bytes.length, sha256, folder: f.folder ?? "/", module, ownerId: ctx.actor.userId ?? null, createdBy: ctx.actor.userId ?? null,
  }).returning();
  const out = toStored(row!);
  await audit(tx, ctx, module ? `${module}.file.uploaded` : "document.uploaded", { type: "document", id }, { filename, mime, size: out.size, sha256 });
  if (!module) await emitEvent(tx, ctx, "core.document.created", { id, title: out.title, mime, size: out.size });
  return out;
}

/** Load a document's metadata + bytes. `module` must match the owner (null = core document). */
export async function readFileById(tx: Tx, d: FileDeps, id: string, module: string | null) {
  const [row] = await tx.select().from(documents)
    .where(and(eq(documents.id, id), isNull(documents.deletedAt), module ? eq(documents.module, module) : isNull(documents.module)));
  if (!row || !row.storageKey) throw notFound("File");
  return { file: toStored(row), bytes: await d.blobs.get(row.storageKey) };
}

export async function deleteFileById(tx: Tx, ctx: RequestContext, id: string, module: string) {
  const r = await tx.update(documents).set({ deletedAt: new Date() })
    .where(and(eq(documents.id, id), eq(documents.module, module), isNull(documents.deletedAt))).returning({ id: documents.id });
  if (!r.length) throw notFound("File");
  await audit(tx, ctx, `${module}.file.deleted`, { type: "document", id });
}


/** Build the configured blob store. FILES_DRIVER=fs (default, FILES_DIR) or s3 (S3_BUCKET, S3_REGION, S3_ENDPOINT?, S3_ACCESS_KEY_ID?, S3_SECRET_ACCESS_KEY?). */
export function fileDepsFromEnv(env: NodeJS.ProcessEnv = process.env): FileDeps {
  const maxBytes = Number(env.FILES_MAX_BYTES ?? 10 * 1_048_576);
  if (!Number.isInteger(maxBytes) || maxBytes < 1024) throw new Error("FILES_MAX_BYTES must be an integer >= 1024");
  if ((env.FILES_DRIVER ?? "fs") === "s3") {
    if (!env.S3_BUCKET || !env.S3_REGION) throw new Error("S3_BUCKET and S3_REGION are required when FILES_DRIVER=s3");
    return { maxBytes, blobs: new S3BlobStore({
      bucket: env.S3_BUCKET, region: env.S3_REGION, endpoint: env.S3_ENDPOINT,
      accessKeyId: env.S3_ACCESS_KEY_ID, secretAccessKey: env.S3_SECRET_ACCESS_KEY,
    }) };
  }
  return { maxBytes, blobs: new FsBlobStore(env.FILES_DIR ?? "./.data/files") };
}
